gWy(){return"\u062d\u062f\u062b \u062e\u0637\u0623\u060c \u062a\u062d\u0642\u0642 \u0645\u0646 \u0627\u062a\u0635\u0627\u0644\u0643 \u0628\u0627\u0644\u0625\u0646\u062a\u0631\u0646\u062a"},
gaxu(){return"\u0623\u0631\u0633\u0644\u0646\u0627 \u0631\u0645\u0632\u064b\u0627 \u0642\u0628\u0644 \u0642\u0644\u064a\u0644. \u0627\u0643\u062a\u0628\u0647 \u0647\u0646\u0627\u060c \u0623\u0648 \u0627\u0646\u062a\u0638\u0631 \u062f\u0642\u064a\u0642\u0629 \u062b\u0645 \u0627\u0637\u0644\u0628 \u0631\u0645\u0632\u064b\u0627 \u062c\u062f\u064a\u062f\u064b\u0627"},
gaxv(){return"\u062a\u062d\u0642\u0642 \u0645\u0646 \u0639\u0646\u0648\u0627\u0646 \u0627\u0644\u0628\u0631\u064a\u062f \u0648\u062d\u0627\u0648\u0644 \u0645\u0631\u0629 \u0623\u062e\u0631\u0649"},
gaxw(){return"\u0627\u0644\u0631\u0645\u0632 \u063a\u064a\u0631 \u0635\u062d\u064a\u062d \u0623\u0648 \u0627\u0646\u062a\u0647\u062a \u0635\u0644\u0627\u062d\u064a\u062a\u0647"},
gaxx(){return"\u062a\u0639\u0630\u0651\u0631 \u062a\u0633\u062c\u064a\u0644 \u0627\u0644\u062f\u062e\u0648\u0644\u060c \u062d\u0627\u0648\u0644 \u0645\u0631\u0629 \u0623\u062e\u0631\u0649"},
gaxy(){return"\u0623\u0647\u0644\u064b\u0627 \u0628\u0639\u0648\u062f\u062a\u0643"},
gaxz(){return"\u062a\u0633\u062c\u064a\u0644 \u0627\u0644\u062f\u062e\u0648\u0644"},
ga9O(){return"\u0623\u0647\u0644\u064b\u0627 \u0628\u0639\u0648\u062f\u062a\u0643"},
a9N(a){return"\u0623\u0647\u0644\u064b\u0627 \u0628\u0639\u0648\u062f\u062a\u0643\u060c "+a},
gaxg(){return"\u0646\u0631\u0633\u0644 \u0625\u0644\u0649 \u0628\u0631\u064a\u062f\u0643 \u0631\u0645\u0632\u064b\u0627 \u0645\u0646 6 \u0623\u0631\u0642\u0627\u0645\u060c \u0648\u062a\u0639\u0648\u062f \u0625\u0644\u0649 \u062d\u0633\u0627\u0628\u0643 \u0648\u0645\u0643\u062a\u0628\u062a\u0643 \u0648\u0646\u0648\u0627\u062f\u064a\u0643 \u0643\u0645\u0627 \u062a\u0631\u0643\u062a\u0647\u0627."},
